/**
 * PostToolUse hook: Auto-lint Python files after Edit/Write.
 *
 * Runs `uv run ruff check --fix`, `uv run ruff format`, and `uv run ty check` on .py
 * files, in the checkout that holds the file: CLAUDE_PROJECT_DIR stays on the main
 * clone while a session edits a linked worktree. A checkout with no `.venv` is
 * skipped, because uv would build one first and a hook must never install.
 * Skips migration files (auto-generated by Django).
 * Ruff failures stay silent (non-blocking). ty failures are surfaced to the
 * model through `hookSpecificOutput.additionalContext` without blocking, since
 * the project rule is that ty must pass before commit but type errors mid-edit
 * are normal.
 *
 * Receives JSON on stdin: { tool_name, tool_input: { file_path, ... } }
 */
import { existsSync, readFileSync } from 'node:fs'
import { execSync } from 'node:child_process'
import { dirname, join, resolve } from 'node:path'

function checkoutOf(file) {
  for (let dir = dirname(resolve(file)); dir !== dirname(dir); dir = dirname(dir)) {
    if (existsSync(join(dir, '.git'))) return dir
  }
  return null
}

let input = {}
try {
  input = JSON.parse(readFileSync(0, 'utf8'))
}
catch {
  process.exit(0)
}
const filePath = input.tool_input?.file_path

if (filePath && /\.py$/.test(filePath) && !/\/migrations\//.test(filePath.replace(/\\/g, '/'))) {
  const cwd = checkoutOf(filePath)
  if (!cwd || !existsSync(join(cwd, '.venv'))) process.exit(0)

  try {
    execSync(`uv run ruff check --fix --quiet ${JSON.stringify(filePath)}`, { cwd, stdio: 'pipe' })
    execSync(`uv run ruff format --quiet ${JSON.stringify(filePath)}`, { cwd, stdio: 'pipe' })
  }
  catch {
    // Ruff errors are non-blocking
  }

  try {
    execSync(`uv run ty check ${JSON.stringify(filePath)}`, { cwd, stdio: 'pipe' })
  }
  catch (err) {
    // Surface ty errors to the model so they get fixed pre-commit, but never block.
    // This goes through `additionalContext` rather than stderr: stderr from a
    // PostToolUse hook that exits 0 only reaches the debug log.
    const out = (err.stdout?.toString() || '') + (err.stderr?.toString() || '')
    if (out.trim()) {
      process.stdout.write(JSON.stringify({
        hookSpecificOutput: {
          hookEventName: 'PostToolUse',
          additionalContext: `ty check found issues in ${filePath}:\n${out.trim()}`,
        },
      }))
    }
  }
}
